#!/usr/bin/env python3
"""Generates crates/reflux/src/settings/timezones.rs from @vvo/tzdb's raw-time-zones.json
(the version in Fluxer's pnpm catalog), for the profile time zone picker.

Usage: scripts/timezones-extract.py path/to/raw-time-zones.json
"""
import json
import sys
from pathlib import Path

raw = json.load(open(sys.argv[1]))
out = Path(__file__).resolve().parent.parent / "crates/reflux/src/settings/timezones.rs"


def q(s):
    return json.dumps(s, ensure_ascii=False)


lines = [
    "//! Generated by scripts/timezones-extract.py from @vvo/tzdb 6.202.0 `raw-time-zones.json`.",
    "//! (name, alternativeName, first two mainCities, search text, rawOffsetInMinutes).",
    "",
    "pub const ZONES: &[(&str, &str, &str, &str, i32)] = &[",
]
for z in raw:
    search = " ".join(x for x in [z["name"], *z["group"], z["alternativeName"], z["countryName"], z["countryCode"], *z["mainCities"]] if x)
    lines.append(f"    ({q(z['name'])}, {q(z['alternativeName'])}, {q(', '.join(z['mainCities'][:2]))}, {q(search)}, {z['rawOffsetInMinutes']}),")
lines.append("];")
out.write_text("\n".join(lines) + "\n")
print(f"{len(raw)} zones -> {out}")
